{
  "PROP-6a4369e9-inv-013": {
    "property_id": "PROP-6a4369e9-inv-013",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-013",
      "classification": "vulnerability",
      "code_path": "beacon_node/beacon_chain/src/data_availability_checker.rs::put_rpc_custody_columns::L240-267",
      "proof_trace": "RPC-imported columns bypass observed_column_sidecars cache. Gossip path calls observe_gossip_data_column (L521 data_column_verification.rs) which updates the cache, but put_rpc_custody_columns only updates observed_slashable. A proposer can publish conflicting columns: column A via gossip gets observed, then column B (different data, same slot/index/proposer) via RPC passes all checks because observed_column_sidecars is never consulted on the RPC path.",
      "attack_scenario": "Attacker proposes block B with data column C1 and publishes C1 via gossip (gets cached in observed_column_sidecars). Attacker then serves conflicting column C2 (same index, different data, same signature) via RPC to specific peers. RPC path imports C2 without checking observed_column_sidecars, allowing two contradictory columns for the same (slot, proposer, index) tuple to coexist across the network.",
      "checklist_id": "PROP-6a4369e9-inv-013"
    },
    "text": "Anti-equivocation cache must be updated for all imported data columns regardless of publishing.",
    "assertion": "forall col: imported(col) => anti_equivocation_cache.contains(col.key)",
    "covers": "SG-010",
    "severity": "HIGH",
    "type": "invariant"
  }
}

